function gateShape(type,x=155,y=50){
 let shape='';const neg=['NAND','NOR','XNOR','NOT'].includes(type),base=({NAND:'AND',NOR:'OR',XNOR:'XOR',NOT:'BUFFER'})[type]||type;
 if(base==='AND')shape=`<path class="gate-shape" d="M${x} ${y}h35a35 35 0 0 1 0 70h-35z"/>`;
 else if(base==='BUFFER')shape=`<path class="gate-shape" d="M${x} ${y}l70 35-70 35z"/>`;
 else shape=`<path class="gate-shape" d="M${x} ${y}Q${x+45} ${y} ${x+75} ${y+35}Q${x+45} ${y+70} ${x} ${y+70}Q${x+25} ${y+35} ${x} ${y}"/>`+(base==='XOR'?`<path class="wire" d="M${x-8} ${y}Q${x+17} ${y+35} ${x-8} ${y+70}"/>`:'');
 return shape+(neg?`<circle class="gate-shape" cx="${x+80}" cy="${y+35}" r="6"/>`:'')+`<text class="gate-label" x="${x+34}" y="${y+40}" text-anchor="middle">${esc(type)}</text>`;
}
const gateDescriptions={AND:'Output is 1 only when both inputs are 1.',OR:'Output is 1 when at least one input is 1. This includes both inputs being 1.',NOT:'Output is the opposite of its single input.',NAND:'Output is the complement of AND: 0 only when both inputs are 1.',NOR:'Output is the complement of OR: 1 only when both inputs are 0.',XOR:'For two inputs, output is 1 exactly when the inputs differ.',XNOR:'For two inputs, output is 1 exactly when the inputs match.',BUFFER:'Output copies its single input unchanged.'};
